def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_actions = [h[1] for h in history]
    my_actions = [h[0] for h in history]
    last_opp = opp_actions[-1]
    last_my = my_actions[-1]

    # Endgame: match defection if opponent starts defecting late
    if n >= 95:
        recent_def = opp_actions[-3:].count('D')
        if recent_def > 0:
            return 'D'
        return 'C'

    # Main game
    recent = opp_actions[-10:] if n >= 10 else opp_actions
    recent_def = recent.count('D')

    if recent_def == 0:
        # Opponent very cooperative. Consider probing if we haven't been retaliated against.
        if 20 <= n < 90:
            my_def_count = my_actions.count('D')
            if my_def_count < 2:
                forgive = 0
                for i in range(n - 1):
                    if my_actions[i] == 'D' and opp_actions[i + 1] == 'C':
                        forgive += 1
                if forgive == my_def_count:
                    if n % 20 == 0:
                        return 'D'
        return 'C'

    if recent_def >= 4:
        return 'D'

    if recent_def == 3:
        if last_opp == 'C':
            return 'C'
        return 'D'

    if recent_def == 2:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if recent_def == 1:
        if last_opp == 'D':
            # Check if isolated and overall very cooperative
            if opp_actions.count('C') / n > 0.8:
                if rng.random() < 0.7:
                    return 'C'
            return 'D'
        else:
            return 'C'

    return 'C'
